<body>
  <div id="root"></div>

  <script>
    const quizQuestions = [
      {
        id: "question-1",
        prompt: "Which of these are commonly used for web development?",
        helpText: "Select every language that is regularly used to build modern websites or web apps.",
        choices: ["JavaScript", "Python", "HTML", "Rust"]
      },
      {
        id: "question-2",
        prompt: "Which languages are primarily known as compiled languages?",
        choices: ["C++", "Go", "Ruby", "Java"]
      },
      {
        id: "question-3",
        prompt: "Which of these are popular programming languages for data science work?",
        choices: ["Python", "R", "SQL", "CSS"]
      }
    ];

    const escapeHtml = (value) =>
      value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");

    function Choice({ name, value, label }) {
      return `
        <label class="choice">
          <input type="checkbox" name="${escapeHtml(name)}" value="${escapeHtml(value)}">
          <span class="choice-text">${escapeHtml(label)}</span>
        </label>
      `;
    }

    function QuestionField({ question, index }) {
      return `
        <div class="form-field">
          <div class="question-number">Question ${index + 1}</div>
          <h2 class="question-title">${escapeHtml(question.prompt)}</h2>
          ${question.helpText ? `<p class="help-text">${escapeHtml(question.helpText)}</p>` : ""}
          <div class="choices">
            ${question.choices
