                Choice({
                  name: question.id,
                  value: `${question.id}-choice-${choiceIndex + 1}`,
                  label: choice
                })
              )
              .join("")}
          </div>
        </div>
      `;
    }

    function QuizForm() {
      return `
        <form id="quiz-form">
          ${quizQuestions.map((question, index) => QuestionField({ question, index })).join("")}
          <div class="actions">
            <button type="submit">Submit Quiz</button>
            <div class="result" id="result" aria-live="polite"></div>
          </div>
        </form>
      `;
    }

    function App() {
      return `
        <main class="app-shell">
          <header class="app-header">
            <p class="eyebrow">Interactive quiz</p>
            <h1>Computer Languages Quiz</h1>
            <p class="intro">Explore a few quick questions about programming and markup languages. Each question allows multiple selections.</p>
          </header>
          ${QuizForm()}
        </main>
      `;
    }

    document.getElementById("root").innerHTML = App();

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
