      const answeredCount = quizQuestions.reduce((count, question) => {
        return count + (formData.getAll(question.id).length > 0 ? 1 : 0);
      }, 0);

      document.getElementById("result").textContent =
        answeredCount === quizQuestions.length
          ? "Quiz submitted. Nice work exploring computer languages."
          : `Quiz submitted. You answered ${answeredCount} of ${quizQuestions.length} questions.`;
