      background: linear-gradient(135deg, var(--accent) 0%, #2563eb 100%);
      box-shadow: 0 12px 30px rgba(37, 99, 235, 0.25);
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 36px rgba(37, 99, 235, 0.34);
    }

    .result {
      min-height: 24px;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 640px) {
      .app-header,
      form {
        padding-left: 20px;
        padding-right: 20px;
      }

      .form-field {
        padding: 18px;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    const quizQuestions = [
      {
        id: "question-1",
        prompt: "Which of these are commonly used for web development?",
        helpText: "Select every language that is regularly used to build modern websites or web apps.",
        choices: ["JavaScript", "Python", "HTML", "Rust"]
      },
      {
        id: "question-2",
        prompt: "Which languages are primarily known as compiled languages?",
        choices: ["C++", "Go", "Ruby", "Java"]
      },
      {
        id: "question-3",
        prompt: "Which of these are popular programming languages for data science work?",
        choices: ["Python", "R", "SQL", "CSS"]
      }
    ];

    const escapeHtml = (value) =>
      value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");

    function Choice({ name, value, label }) {
      return `
        <label class="choice">
          <input type="checkbox" name="${escapeHtml(name)}" value="${escapeHtml(value)}">
          <span class="choice-text">${escapeHtml(label)}</span>
        </label>
      `;
    }

    function QuestionField({ question, index }) {
      return `
        <div class="form-field">
          <div class="question-number">Question ${index + 1}</div>
          <h2 class="question-title">${escapeHtml(question.prompt)}</h2>
          ${question.helpText ? `<p class="help-text">${escapeHtml(question.helpText)}</p>` : ""}
          <div class="choices">
            ${question.choices
              .map((choice, choiceIndex) =>
                Choice({
                  name: question.id,
                  value: `${question.id}-choice-${choiceIndex + 1}`,
                  label: choice
                })
              )
              .join("")}
          </div>
        </div>
      `;
    }

    function QuizForm() {
      return `
        <form id="quiz-form">
          ${quizQuestions.map((question, index) => QuestionField({ question, index })).join("")}
          <div class="actions">
            <button type="submit">Submit Quiz</button>
            <div class="result" id="result" aria-live="polite"></div>
          </div>
        </form>
      `;
    }

    function App() {
      return `
        <main class="app-shell">
          <header class="app-header">
            <p class="eyebrow">Interactive quiz</p>
            <h1>Computer Languages Quiz</h1>
            <p class="intro">Explore a few quick questions about programming and markup languages. Each question allows multiple selections.</p>
          </header>
          ${QuizForm()}
        </main>
      `;
    }

    document.getElementById("root").innerHTML = App();

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();
      const formData = new FormData(event.currentTarget);
      const answeredCount = quizQuestions.reduce((count, question) => {
        return count + (formData.getAll(question.id).length > 0 ? 1 : 0);
      }, 0);

      document.getElementById("result").textContent =
        answeredCount === quizQuestions.length
          ? "Quiz submitted. Nice work exploring computer languages."
          : `Quiz submitted. You answered ${answeredCount} of ${quizQuestions.length} questions.`;
    });
  </script>
</body>
</html>
